UPDATE `fa_cms_home_section` SET `section_name`='产品中心',`title`='产品中心',`subtitle`='联合高校协同研发一系列涂料和新技术，以及配套的施工方法',`content`='水包水、水包砂型仿石漆，是科创美创新力作。细腻呈现各类石材纹理，远观与真石无异。兼具良好柔韧性与耐候性，能适应墙面细微变形 ......',`more_text`='',`more_url`='#',`config_json`='{"other_title":"其他涂料","other_summary":"丙烯酸地坪、聚氨酯地坪、环氧地坪、发射隔热涂料，氟碳涂料等特色产品，为建筑增添别样魅力.....","other_url":"#","pc_slugs":["fsq","rjq","zsq","hydp","jazdp","bxsdp","jgsgh"],"mobile_slugs":["fsq","rjq","zsq"]}',`source_key`='clone:home:products',`weigh`=700,`updatetime`=@clone_now WHERE `section_key`='products' AND `edited_by_admin`=0;
UPDATE `fa_cms_home_section` SET `section_name`='服务能力',`title`='建筑涂料生产施工一体化服务',`subtitle`='科创美为您提供个性化的定制设计图服务，从设计到施工无缝对接',`content`='',`more_text`='点击咨询',`more_url`='http://wpa.qq.com/msgrd?v=3&uin=null&site=qq&menu=yes',`config_json`='{"metrics":[{"value":"1v1","unit":"落地","text":"专属项目经理全程跟进","icon":"/uploads/cms-clone/pc/images/td_ic1.png","prefix":""},{"value":"500","unit":"人","text":"施工团队","icon":"/uploads/cms-clone/pc/images/td_ic2.png","prefix":""},{"value":"2+1","unit":"","text":"2年质保+1年延长质保","icon":"/uploads/cms-clone/pc/images/td_ic3.png","prefix":"质保"},{"value":"24","unit":"小时","text":"省内24小时响应","icon":"/uploads/cms-clone/pc/images/td_ic4.png","prefix":""}]}',`source_key`='clone:home:service',`weigh`=600,`updatetime`=@clone_now WHERE `section_key`='service' AND `edited_by_admin`=0;
UPDATE `fa_cms_home_section` SET `section_name`='工程案例',`title`='工程案例',`subtitle`='施工项目遍布安徽省，涂装施工面积超1亿㎡',`content`='经过精心施工与严格管控，合肥神马外墙翻新工程顺利收官。斑驳老旧的外墙焕发新颜，既...',`more_text`='',`more_url`='#',`config_json`='{"pc_slugs":["hfsmkj","ahsmms","wqgcym","hfhdsy","ahkcmt4645","ahyxfz"],"mobile_slugs":["hfsmkj","ahsmms","wqgcym","hfhdsy","ahkcmt4645","ahyxfz","ahkcmt8586","zlhkcx","czdthx","hfndbw"]}',`source_key`='clone:home:cases',`weigh`=500,`updatetime`=@clone_now WHERE `section_key`='cases' AND `edited_by_admin`=0;
UPDATE `fa_cms_home_section` SET `section_name`='企业优势',`title`='我们的优势',`subtitle`='5S现场管理，能应对各类复杂墙面的涂装施工',`content`='科创美设有涂料技术研发中心，和中国科学技术大学、安徽建筑大学等多所高校长期科研合作，成果丰硕，推出诸多新产品、新技术与配套施工方法，揽获25项国家专利。同时，从材料源头严格把控，保障产品稳定性，为项目品质护航。',`more_text`='',`more_url`='',`config_json`='{"items":[{"title":"涂料研发中心","subtitle":"优化涂料品质性能","text":"科创美设有涂料技术研发中心，和中国科学技术大学、安徽建筑大学等多所高校长期科研合作，成果丰硕，推出诸多新产品、新技术与配套施工方法，揽获25项国家专利。同时，从材料源头严格把控，保障产品稳定性，为项目品质护航。","image":"/uploads/cms-clone/pc/images/ys1.jpg","icon":"/uploads/cms-clone/pc/images/ys_ic1.png","url":""},{"title":"23年经验厂家","subtitle":"涂料生产及施工一站式","text":"自有产权厂房约2万㎡，拥有全自动智能生产线3条，日产能300吨，产能位居华东地区前三，充分满足大型项目的供货需求。具有国家二级专业施工资质，现有施工团队500人，面对各类涂料施工项目，均能给予强有力保障。","image":"/uploads/cms-clone/pc/images/ys2.jpg","icon":"/uploads/cms-clone/pc/images/ys_ic2.png","url":""},{"title":"5S现场管理","subtitle":"保障施工安全无虞","text":"科创美拥有一支18人的安全管理安全团队，施工过程中执行严格的安全管理措施及安全检查措施，且为所有项目都购买团体意外保险，为工人、业主双向兜底，全方位保障施工安全无虞。","image":"/uploads/cms-clone/pc/images/ys3.jpg","icon":"/uploads/cms-clone/pc/images/ys_ic3.png","url":""},{"title":"工程按时交付","subtitle":"质保售后更安心","text":"严格依约施工，确保工期无误，不负业主信赖。售后特推 “质保2+1”模式，施工后2年质保，再加1年延保。后期修补时，把握材料特性与配比，自主生产供应材料，有效降低修补色差，确保工程持久耐用。","image":"/uploads/cms-clone/pc/images/ys4.jpg","icon":"/uploads/cms-clone/pc/images/ys_ic4.png","url":""}]}',`source_key`='clone:home:advantages',`weigh`=400,`updatetime`=@clone_now WHERE `section_key`='advantages' AND `edited_by_admin`=0;
UPDATE `fa_cms_home_section` SET `section_name`='公司介绍',`title`='关于科创美',`subtitle`='',`content`='科创美专注建筑涂料生产与施工23年，是国家高新技术企业、专精特新企业，拥有建筑装饰装修及防水防腐保温国家级专业施工资质。公司拥有年产能10万吨的全自动涂料生产线以及全年1000万平米的施工交付能力，为墙面、地面、屋面提供一站式综合涂料解决方案。',`more_text`='',`more_url`='/page/about',`config_json`='{"social_text_1":"关注科创美抖音","social_text_2":"关注科创美视频号","media_items":[{"title":"厂房涂装工程","image":"","video_url":"http://mpv.videocc.net/2b8fd4c754/f/2b8fd4c754f67199c23b8ab29e33992f_1.mp4","url":""},{"title":"地坪涂装工程","image":"/uploads/cms-clone/pc/images/yz2.jpg","video_url":"http://mpv.videocc.net/2b8fd4c754/f/2b8fd4c7544aaad89bc37aa61c18babf_1.mp4","url":""},{"title":"屋面彩瓦涂装工程","image":"/uploads/cms-clone/pc/images/yz3.jpg","video_url":"http://mpv.videocc.net/2b8fd4c754/0/2b8fd4c75482485fb2800bded0182030_1.mp4","url":""},{"title":"建筑涂料生产区","image":"/uploads/cms-clone/pc/images/yz4.jpg","video_url":"http://mpv.videocc.net/2b8fd4c754/6/2b8fd4c754e752aeb9ccc11732db6236_1.mp4","url":""},{"title":"涂料研发中心","image":"/uploads/cms-clone/pc/images/yz5.jpg","video_url":"http://mpv.videocc.net/2b8fd4c754/6/2b8fd4c754b6eb7de986f82a46c3de86_1.mp4","url":""},{"title":"样品展厅","image":"/uploads/cms-clone/pc/images/yz6.jpg","video_url":"http://mpv.videocc.net/2b8fd4c754/b/2b8fd4c754b458ed84e3d8d9f637503b_1.mp4","url":""}]}',`source_key`='clone:home:about',`weigh`=300,`updatetime`=@clone_now WHERE `section_key`='about' AND `edited_by_admin`=0;
UPDATE `fa_cms_home_section` SET `section_name`='新闻动态',`title`='最新动态',`subtitle`='关注科创美，了解品牌新闻和产品知识',`content`='安徽科创美涂料科技股份有限公司在二十年的外墙修缮经验中发现，近一半的翻新问题源于基层处理不当。基层质量若不达标，即使使用...',`more_text`='查看更多',`more_url`='/news',`config_json`='{"left_title":"科创美新闻","left_url":"/article_kcmxw.html","right_title":"常见问答","right_url":"/article_cjwd.html","pc_slugs":["jcmclc","kcmfsz5731","hfcffx","wqfxxc","ahcfwq7739","kcmtlx","kcmfsq5567","ahkcmc","wsmyly","xzzsqx","wqfsqd","rhbbfs"],"mobile_slugs":["cljcfd","hfcsgx","ahmmsm","hfwdrl"]}',`source_key`='clone:home:news',`weigh`=200,`updatetime`=@clone_now WHERE `section_key`='news' AND `edited_by_admin`=0;
UPDATE `fa_cms_home_section` SET `section_name`='走进科创美',`title`='走进科创美',`subtitle`='',`content`='安徽科创美涂料科技股份有限公司成立于2003年，专门从事建筑墙面涂料生产与施工的规模化企业。作为一家集产、学、研于一体的国家高新技术企业，先后服务过中铁四局、合肥城改、合肥城建、淮矿地产、中梁控股、绿地集团、旭辉地产等近2000家业主单位。',`background_image`='/uploads/cms-clone/pc/images/abt_bg.jpg',`mobile_background_image`='/uploads/cms-clone/mobile/images/abt.jpg',`more_text`='探索更多',`more_url`='/page/about',`config_json`='{"media_items":[{"title":"科创美20周年庆典","image":"","video_url":"https://nsyconsole.nswyun.com/#/polyPlayer?type=H5&id=27432","url":"/page/about"},{"title":"科创美厂区宣传","image":"","video_url":"https://nsyconsole.nswyun.com/#/polyPlayer?type=H5&id=31680","url":"/page/about"},{"title":"科创美厂房施工","image":"","video_url":"https://nsyconsole.nswyun.com/#/polyPlayer?type=H5&id=31808","url":"/page/about"},{"title":"科创美涡阳培训会","image":"","video_url":"https://nsyconsole.nswyun.com/#/polyPlayer?type=H5&id=31806","url":"/page/about"}]}',`source_key`='clone:home:company',`weigh`=100,`updatetime`=@clone_now WHERE `section_key`='company' AND `edited_by_admin`=0;


